// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address ownerArg, address collateralArg, address debtArg, address factoryArg) public {
        // keep the admissible domain wide: args must simply be distinct addresses so the
        // owner slot (0x0) and the collateral slot (0x14) hold different values.
        vm.assume(ownerArg != collateralArg);
        vm.assume(debtArg != collateralArg);
        vm.assume(factoryArg != collateralArg);

        // Build clone-style calldata: 4-byte selector + immutable args + 2-byte extraLength.
        bytes memory args = abi.encodePacked(ownerArg, collateralArg, debtArg, factoryArg);
        uint16 extraLength = uint16(args.length);
        bytes memory payload = abi.encodePacked(c.collateral.selector, args, extraLength);

        (bool ok, bytes memory ret) = address(c).call(payload);

        address returned;
        if (ok && ret.length >= 32) {
            returned = abi.decode(ret, (address));
        }

        // General rule: collateral() always returns the immutable arg stored at offset 0x14,
        // i.e. exactly collateralArg. The mutant reads offset 0x0 and returns ownerArg !=
        // collateralArg, breaking the rule for every admissible input.
        assertTrue(ok && returned == collateralArg);
    }
}
